"use client"

import * as React from "react"
import { toast } from "sonner"

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { TooltipProvider } from "@/components/ui/tooltip"
import { CloneVoiceFlow } from "@/components/mockups/voice-cloning/clone-voice-flow"
import { PersonaVoice } from "@/components/mockups/voice-cloning/persona-voice"
import { VoiceLibrary } from "@/components/mockups/voice-cloning/voice-library"
import { AppShell } from "@/components/shell/app-shell"
import { MockupShell } from "@/components/shell/mockup-shell"
import {
  OUTCOMES,
  PERSONA,
  type SampleOutcome,
  type Viewer,
  type Voice,
  voicesFor,
} from "@/lib/mockups/voice-cloning-data"

/**
 * Voice cloning — DES-198, under INT-191, for PLT-4472. The spec is the PRD
 * "Voice cloning on the platform" (DIS-71).
 *
 * Two places the flow starts from, one flow:
 *  - Voice library: Clone voice beside Add voice, the new Pending status, and
 *    delete on cloned voices (blocked while a persona uses one).
 *  - Persona: the voice picker, own voices above Sarj's, Clone a voice at its
 *    foot; the new voice comes back selected.
 *
 * The bar holds what a reviewer needs to reach every state: the surface, who
 * is looking (only Sarj users get the publish request, and Add voice), and
 * how the sample turns out — clean, noisy, or a clone that fails once.
 */

const SURFACES = [
  { id: "library", label: "Voice library" },
  { id: "persona", label: "Persona" },
] as const

type Surface = (typeof SURFACES)[number]["id"]

const VIEWERS: { id: Viewer; label: string }[] = [
  { id: "client", label: "Client org" },
  { id: "sarj", label: "Sarj" },
]

export default function VoiceCloningPage() {
  const [surface, setSurface] = React.useState<Surface>("library")
  const [viewer, setViewer] = React.useState<Viewer>("client")
  const [outcome, setOutcome] = React.useState<SampleOutcome>("clean")
  const [voices, setVoices] = React.useState<Voice[]>(() => voicesFor("client"))
  const [voiceId, setVoiceId] = React.useState(PERSONA.voiceId)
  const [cloning, setCloning] = React.useState(false)

  const changeViewer = (next: Viewer) => {
    setViewer(next)
    setVoices(voicesFor(next))
    setVoiceId(PERSONA.voiceId)
  }

  const created = (voice: Voice) => {
    setVoices((current) => [voice, ...current])
    if (surface === "persona") {
      if (
        voice.language === PERSONA.language &&
        voice.gender === PERSONA.gender
      ) {
        setVoiceId(voice.id)
      }
      return
    }
    toast(
      voice.status === "pending"
        ? `${voice.name} created. Publishing is pending approval.`
        : `${voice.name} created`,
    )
  }

  return (
    <MockupShell
      actions={
        <>
          <Select
            onValueChange={(value) => setOutcome(value as SampleOutcome)}
            value={outcome}
          >
            <SelectTrigger aria-label="Sample outcome" size="sm">
              <SelectValue />
            </SelectTrigger>
            <SelectContent align="end" position="popper">
              {OUTCOMES.map((entry) => (
                <SelectItem key={entry.id} value={entry.id}>
                  {entry.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <ToggleGroup
            aria-label="Viewer"
            onValueChange={(next) => {
              if (next) changeViewer(next as Viewer)
            }}
            size="sm"
            type="single"
            value={viewer}
            variant="outline"
          >
            {VIEWERS.map((entry) => (
              <ToggleGroupItem key={entry.id} value={entry.id}>
                {entry.label}
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
          <ToggleGroup
            aria-label="Surface"
            onValueChange={(next) => {
              if (next) setSurface(next as Surface)
            }}
            size="sm"
            type="single"
            value={surface}
            variant="outline"
          >
            {SURFACES.map((entry) => (
              <ToggleGroupItem key={entry.id} value={entry.id}>
                {entry.label}
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
        </>
      }
      title="Voice cloning on the platform"
    >
      <TooltipProvider>
        {surface === "library" ? (
          <AppShell active="Voice Library">
            <VoiceLibrary
              onClone={() => setCloning(true)}
              onDelete={(voice) =>
                setVoices((current) =>
                  current.filter((entry) => entry.id !== voice.id),
                )
              }
              viewer={viewer}
              voices={voices}
            />
          </AppShell>
        ) : (
          <AppShell active="Personas" breadcrumb={["Personas", PERSONA.name]}>
            <PersonaVoice
              onClone={() => setCloning(true)}
              onVoiceChange={setVoiceId}
              voiceId={voiceId}
              voices={voices}
            />
          </AppShell>
        )}

        {/* From a persona the flow starts on its language and gender, so the
            clone lands in that persona's cards. Keyed so switching surface or
            viewer opens a fresh flow. */}
        <CloneVoiceFlow
          canPublish={viewer === "sarj"}
          defaults={{ language: PERSONA.language, gender: PERSONA.gender }}
          key={`${surface}-${viewer}`}
          onCreated={created}
          onOpenChange={setCloning}
          open={cloning}
          outcome={outcome}
        />
      </TooltipProvider>
    </MockupShell>
  )
}

"use client"

import {
  Alert02Icon,
  Archive02Icon,
  ArrowDataTransferVerticalIcon,
  ArrowDown01Icon,
  ArrowDownLeft01Icon,
  ArrowLeft01Icon,
  ArrowRight01Icon,
  ArrowUp01Icon,
  ArrowUpRight01Icon,
  BookOpen02Icon,
  Building02Icon,
  CallOutgoing01Icon,
  BubbleChatIcon,
  Calendar03Icon,
  Cancel01Icon,
  CancelCircleIcon,
  CheckmarkCircle02Icon,
  Clock01Icon,
  Coins01Icon,
  ColorsIcon,
  ComponentIcon,
  Copy01Icon,
  CopyLinkIcon as CopyLinkGlyph,
  CpuIcon,
  CubeIcon,
  DashboardSquare01Icon,
  Delete02Icon,
  Download01Icon,
  EaseCurveControlPointsIcon,
  FileValidationIcon,
  FilterIcon,
  Home01Icon,
  InformationCircleIcon,
  MoreHorizontalIcon,
  PencilEdit02Icon,
  PlayIcon,
  PlusSignIcon,
  RefreshIcon,
  Robot01Icon,
  Search01Icon,
  SearchRemoveIcon,
  Tick02Icon,
  GlobalIcon,
  File01Icon,
  TextIcon,
  FolderAddIcon,
  FolderSyncIcon,
  ArrowLeft02Icon,
  ArrowRight02Icon,
  BankIcon,
  DashedLineCircleIcon,
  Hospital01Icon,
  RealEstate01Icon,
  Restaurant01Icon,
  ShoppingBag01Icon,
  SmartPhone01Icon,
  SparklesIcon,
  AlertCircleIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

/* The icon rule's example: ordinary actions, because the point of that card is
   one size and one stroke weight rather than the glyphs themselves. */
export const PreviewIcon = icon(PlayIcon, "PreviewIcon")
export const NarrowIcon = icon(FilterIcon, "NarrowIcon")
export const ExportIcon = icon(Download01Icon, "ExportIcon")
export const DeleteIcon = icon(Delete02Icon, "DeleteIcon")

/** The two a row carries. Named for the row, not for the glyph. */
export const EditRowIcon = icon(PencilEdit02Icon, "EditRowIcon")

/** Sorting: the active direction, and the affordance on a column that is not sorted. */
export const SortAscIcon = icon(ArrowUp01Icon, "SortAscIcon")
export const SortDescIcon = icon(ArrowDown01Icon, "SortDescIcon")
export const SortableIcon = icon(ArrowDataTransferVerticalIcon, "SortableIcon")

/** Direction, which is what tells the two neutral chips apart. */
export const InboundIcon = icon(ArrowDownLeft01Icon, "InboundIcon")
export const OutboundIcon = icon(ArrowUpRight01Icon, "OutboundIcon")

/** The four call states. */
export const CompletedIcon = icon(CheckmarkCircle02Icon, "CompletedIcon")
export const FailedIcon = icon(CancelCircleIcon, "FailedIcon")
export const RunningIcon = icon(Clock01Icon, "RunningIcon")
export const ScheduledIcon = icon(Calendar03Icon, "ScheduledIcon")

/* The close control on the drawer demo's header — the house shape is a title,
   a description and this button, with no icon tile beside the title. */
export const CloseIcon = icon(Cancel01Icon, "CloseIcon")

export const RowMenuIcon = icon(MoreHorizontalIcon, "RowMenuIcon")
export const SearchIcon = icon(Search01Icon, "SearchIcon")

/* The multi-step form explains its fields with an (i) beside the label rather
   than a line under it — the reference it is built from does, and a screen
   uses one language for all of its fields or the other. */
export const HintIcon = icon(InformationCircleIcon, "HintIcon")
export const WarningIcon = icon(Alert02Icon, "WarningIcon")

/** A bare tick, for a step already done. `CompletedIcon` is a circled one and
    would sit inside the stepper's own circle. */
export const StepDoneIcon = icon(Tick02Icon, "StepDoneIcon")

/* The rail's disclosure chevron. It points down when the section is open and
   is rotated a quarter turn when it is not, so one glyph carries both states
   rather than two glyphs that have to be told apart. */
export const SectionToggleIcon = icon(ArrowDown01Icon, "SectionToggleIcon")

/* The tabs demo. One glyph per view of the same call, each naming what that
   view holds — the bar is the thing being demonstrated, so the labels carry
   an icon the way a real settings or record bar does. */
export const TranscriptIcon = icon(BubbleChatIcon, "TranscriptIcon")
export const ModelIcon = icon(CpuIcon, "ModelIcon")
export const CostIcon = icon(Coins01Icon, "CostIcon")

/* The header control that hands this exact topic to someone. The tick is the
   same glyph a finished step uses — one "done" mark across the reference,
   rather than a second one that has to be learned. */
export const CopyLinkIcon = icon(CopyLinkGlyph, "CopyLinkIcon")
export const CopiedIcon = icon(Tick02Icon, "CopiedIcon")

/* Copies a whole section out as a skill file. */
export const CopySkillIcon = icon(Copy01Icon, "CopySkillIcon")

/* The three states that are not the populated one, each named for the state
   rather than the glyph: nothing here yet, nothing matched, and it broke. */
export const NoResultsIcon = icon(SearchRemoveIcon, "NoResultsIcon")
export const SourceIcon = icon(BookOpen02Icon, "SourceIcon")
export const RetryIcon = icon(RefreshIcon, "RetryIcon")

/* The ring's way back up a level: from one section's topics to the five
   sections themselves. Named for where it goes rather than for the arrow,
   because the same glyph points back to two different places on this page. */
export const AllSectionsIcon = icon(ArrowLeft01Icon, "AllSectionsIcon")

/** The trailing mark on a section row on the overview. */
export const OpenSectionIcon = icon(ArrowRight01Icon, "OpenSectionIcon")

/* One per section on the overview. Named for the shelf, not the glyph, and
   present for the reason the house rules allow an icon in a list at all: five
   cards that differ only by a word are quicker to tell apart with a mark than
   without one. Nothing else on that page carries an icon. */
export const FoundationsIcon = icon(ColorsIcon, "FoundationsIcon")
export const MotionSectionIcon = icon(
  EaseCurveControlPointsIcon,
  "MotionSectionIcon",
)
export const PatternsIcon = icon(DashboardSquare01Icon, "PatternsIcon")
export const CustomComponentsIcon = icon(CubeIcon, "CustomComponentsIcon")
export const ShadcnComponentsIcon = icon(ComponentIcon, "ShadcnComponentsIcon")

/* The Icons tile's subject: one everyday glyph from the set the product draws
   from, set on its construction sheet by the tile's drawing. */
export const IconsTopicGlyph = icon(Home01Icon, "IconsTopicGlyph")

/* The index-page demo's header action. */
export const StartCallIcon = icon(CallOutgoing01Icon, "StartCallIcon")

/* The scenarios index: its two header tiles, the admin scope, and the row's
   one icon action. */
export const CreateScenarioIcon = icon(PlusSignIcon, "CreateScenarioIcon")
export const PlaygroundIcon = icon(Robot01Icon, "PlaygroundIcon")
export const OrganisationIcon = icon(Building02Icon, "OrganisationIcon")
export const CreateTemplateIcon = icon(FileValidationIcon, "CreateTemplateIcon")
export const ActiveIcon = icon(CheckmarkCircle02Icon, "ActiveIcon")
export const DeletedIcon = icon(Delete02Icon, "DeletedIcon")

/* The knowledge base's five ways in, as its header tiles. */
export const AddUrlIcon = icon(GlobalIcon, "AddUrlIcon")
export const AddFilesIcon = icon(File01Icon, "AddFilesIcon")
export const AddTextIcon = icon(TextIcon, "AddTextIcon")
export const CreateFolderIcon = icon(FolderAddIcon, "CreateFolderIcon")
export const SyncDocumentsIcon = icon(FolderSyncIcon, "SyncDocumentsIcon")

/* Surfaces: the demos under Components › Choosing a surface. */
export const ArchiveIcon = icon(Archive02Icon, "ArchiveIcon")
export const PreviousRecordIcon = icon(ArrowUp01Icon, "PreviousRecordIcon")
export const NextRecordIcon = icon(ArrowDown01Icon, "NextRecordIcon")
export const CreateInListIcon = icon(PlusSignIcon, "CreateInListIcon")
export const CopyKeyIcon = icon(Copy01Icon, "CopyKeyIcon")

/* Creation flow: the ways to start a scenario, and the industries its
   templates are filed under. */
export const StartBlankIcon = icon(DashedLineCircleIcon, "StartBlankIcon")
export const ChooseStartIcon = icon(ArrowRight02Icon, "ChooseStartIcon")
export const StepBackIcon = icon(ArrowLeft02Icon, "StepBackIcon")
export const BuildWithAiIcon = icon(SparklesIcon, "BuildWithAiIcon")
export const HealthcareIcon = icon(Hospital01Icon, "HealthcareIcon")
export const TelecomIcon = icon(SmartPhone01Icon, "TelecomIcon")
export const BankingIcon = icon(BankIcon, "BankingIcon")
export const RestaurantsIcon = icon(Restaurant01Icon, "RestaurantsIcon")
export const RetailIcon = icon(ShoppingBag01Icon, "RetailIcon")
export const RealEstateIcon = icon(RealEstate01Icon, "RealEstateIcon")

/* JSON: the fold toggle on an object's opening line, and copy. */
export const FoldIcon = icon(ArrowRight01Icon, "FoldIcon")
export const CopyJsonIcon = icon(Copy01Icon, "CopyJsonIcon")

/* Alerts: the error intent's glyph. Neutral, success and warning reuse
   HintIcon, CompletedIcon and WarningIcon. */
export const ErrorAlertIcon = icon(AlertCircleIcon, "ErrorAlertIcon")

"use client"

import * as React from "react"

import { cva, type VariantProps } from "class-variance-authority"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"

import { CloseIcon, StepDoneIcon } from "@/components/design-system/icons"
import { Button } from "@/components/ui/button"
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Spinner } from "@/components/ui/spinner"
import {
  Stepper,
  StepperIndicator,
  StepperItem,
  StepperNav,
  StepperSeparator,
  StepperTrigger,
} from "@/components/ui/stepper"
import { cn } from "@/lib/utils"

/**
 * The multi-step form container from 21st.dev (@ravikatiyar162), on this
 * repo's primitives.
 *
 * Its structure, props and motion are unchanged. What could not come across:
 *
 * - Its own copies of Card, Button, Progress, Input, Label, Select, Tooltip
 *   and Alert are older shadcn than the ones here, and dropping them into
 *   `components/ui` would have replaced primitives this repo has customised —
 *   a `Card` with `shadow-sm` instead of the ring, a `Button` with `h-10 px-4`
 *   instead of this scale. They are the same components by name only.
 * - `framer-motion` is the old package name; `motion` is installed and is the
 *   same library.
 * - The `lucide-react` X is a second icon set, so it is the HugeIcons close.
 * - `md:w-[700px]` and `min-h-[300px]` are off-scale, so they are the nearest
 *   scale steps.
 * - Colour needed no work: it was already on `muted-foreground` and `primary`.
 *
 * Added, because the shell around it needs them: `nextButtonText` takes a node
 * so a spinner can sit in the button, and `nextDisabled` covers submitting.
 */

/* Enter and exit want ease-out, and this is --ease-out-cubic from globals.css.
   The spring it replaces sat at a 0.87 damping ratio, so every step overshot
   and settled — bounce belongs on a drag, not on pressing Next. */
const EASE_OUT_CUBIC = [0.33, 1, 0.68, 1] as const

/* Exit shorter than enter. `mode="wait"` runs them back to back, so the two
   durations add up: 300ms total is the dialog budget, and weighting it towards
   the arriving step is what stops the gap reading as a stall. */
const EXIT = { duration: 0.12, ease: EASE_OUT_CUBIC }
const ENTER = { duration: 0.18, ease: EASE_OUT_CUBIC }

/* The container resizing is an on-screen morph, not an entrance, so it takes
   ease-in-out — --ease-in-out-cubic from globals.css. 300ms because the panel
   is the largest thing moving; the step content underneath is quicker. */
const EASE_IN_OUT_CUBIC = [0.645, 0.045, 0.355, 1] as const
const RESIZE = { duration: 0.3, ease: EASE_IN_OUT_CUBIC }

/* 24px, not the 100px this shipped with. Past about 30px the panel reads as
   flying in from somewhere rather than as the next step arriving. */
const TRAVEL = 24

const multiStepFormVariants = cva("flex flex-col", {
  variants: {
    size: {
      default: "md:max-w-2xl",
      sm: "md:max-w-xl",
      lg: "md:max-w-3xl",
    },
  },
  defaultVariants: {
    size: "default",
  },
})

interface MultiStepFormProps
  extends
    Omit<React.HTMLAttributes<HTMLDivElement>, "title">,
    VariantProps<typeof multiStepFormVariants> {
  currentStep: number
  totalSteps: number
  title: string
  description: string
  onBack: () => void
  onNext: () => void
  onClose?: () => void
  backButtonText?: string
  nextButtonText?: React.ReactNode
  nextDisabled?: boolean
  /** Sits between the body and the footer, outside the step animation. */
  notice?: React.ReactNode
  /** Jumping back. Only ever called with a step already completed. */
  onStepSelect?: (step: number) => void
  footerContent?: React.ReactNode
}

const MultiStepForm = React.forwardRef<HTMLDivElement, MultiStepFormProps>(
  (
    {
      className,
      size,
      currentStep,
      totalSteps,
      title,
      description,
      onBack,
      onNext,
      onClose,
      backButtonText = "Back",
      nextButtonText = "Next step",
      nextDisabled = false,
      notice,
      onStepSelect,
      footerContent,
      children,
      ...props
    },
    ref,
  ) => {
    const reduce = useReducedMotion()

    /* Which way the reader is travelling. Without it Back played the forward
       animation, so the content slid in from the same side either way and the
       one thing the motion is for — which direction you just went — was the
       one thing it did not say.

       Adjusted during render rather than held in a ref: a ref mutated while
       rendering is read a second time under StrictMode's double render, by
       which point it already equals the new step, and every move looks like a
       forward one. */
    /* height: "auto" until the first measurement, so the first paint is the
       real height rather than zero. */
    const innerRef = React.useRef<HTMLDivElement>(null)
    const [height, setHeight] = React.useState<"auto" | number>("auto")
    const [morphing, setMorphing] = React.useState(false)

    React.useLayoutEffect(() => {
      const inner = innerRef.current
      if (!inner) return

      const observer = new ResizeObserver(([entry]) => {
        setHeight(entry.contentRect.height)
      })
      observer.observe(inner)
      return () => observer.disconnect()
    }, [])

    const [previous, setPrevious] = React.useState(currentStep)
    const [direction, setDirection] = React.useState(1)

    if (previous !== currentStep) {
      setDirection(currentStep > previous ? 1 : -1)
      setPrevious(currentStep)
    }

    const variants = {
      hidden: (way: number) => ({ opacity: 0, x: way * TRAVEL }),
      enter: { opacity: 1, x: 0, transition: ENTER },
      exit: (way: number) => ({
        opacity: 0,
        x: way * -TRAVEL,
        transition: EXIT,
      }),
    }

    return (
      <Card
        className={cn(multiStepFormVariants({ size }), className)}
        ref={ref}
        {...props}
      >
        <CardHeader>
          {/* Title and description in one column with Close beside both, the
              shape AGENTS.md fixes for a drawer header. Close was inside the
              title row before, and at 28px it made that row taller than the
              20px title — which pushed the description a whole button-height
              away from the thing it describes. */}
          <div className="flex flex-row items-start justify-between gap-4">
            <div className="flex flex-col gap-0.5">
              <CardTitle>{title}</CardTitle>
              <CardDescription>{description}</CardDescription>
            </div>
            {onClose ? (
              <Button
                aria-label="Close"
                onClick={onClose}
                size="icon-sm"
                variant="ghost"
              >
                <CloseIcon />
              </Button>
            ) : null}
          </div>
        </CardHeader>

        {/* Its own block rather than the last child of CardHeader: in there it
            inherited the header's gap-1, which is the title-to-description
            step, so the steps sat as close to the description as the
            description sits to the title. Out here the card's own spacing
            applies on both sides and the three zones read as three. */}
        <div className="px-(--card-spacing)">
          {/* A stepper rather than a bar: the bar said how far along and
              nothing else, and this form has a failure that names a step, so
              per-step state is worth having. The number stays inside the
              indicator — five bare dots say where you are but not what is
              there — and the tick replaces it once the step is behind you. */}
          <Stepper
            indicators={{
              completed: <StepDoneIcon className="size-3.5" />,
              loading: <Spinner className="size-3.5" />,
            }}
            onValueChange={onStepSelect}
            value={currentStep}
          >
            <StepperNav>
              {Array.from({ length: totalSteps }, (_, index) => index + 1).map(
                (step) => (
                  /* Every step is reachable, forward included. Note this is
                     the opposite of the "Jumping back" line in the anatomy
                     below — asked for deliberately, so the rule is the thing
                     to change if the two should agree. */
                  <StepperItem
                    key={step}
                    loading={nextDisabled && step === currentStep}
                    step={step}
                  >
                    <StepperTrigger>
                      {/* The fill and the glyph are one event. Colour is paint,
                          but this is a 24px circle — the rule against paint
                          animation is about large surfaces.

                          The tick is drawn rather than zoomed in: it is written
                          along its own path, left to right, the same way the
                          line before it fills. See the note on INDICATOR in
                          stepper-preview.tsx for how the dash length is picked;
                          the two are the same component and animate alike. */}
                      <StepperIndicator className="size-6 transition-colors duration-200 ease-out-cubic motion-reduce:transition-none data-[state=completed]:bg-success data-[state=completed]:text-success-foreground data-[state=completed]:[&_svg_path]:[--draw-length:22] data-[state=completed]:[&_svg_path]:[stroke-dasharray:var(--draw-length)] data-[state=completed]:[&_svg_path]:animate-draw-stroke motion-reduce:[&_svg_path]:animate-none">
                        {step}
                      </StepperIndicator>
                    </StepperTrigger>
                    {step < totalSteps ? (
                      /* The fill travels rather than switching colour: a line
                         that turns green all at once says a step is done, a
                         line that fills says which way you are going. scaleX on
                         an overlay keeps it on the compositor — animating the
                         bar's own width would be layout.

                         mx-0 over the primitive's own m-0.5: both ends of this
                         line meet a circle, and 2px short of one at each end is
                         a line laid between the steps rather than the track
                         that carries you along them. */
                      <StepperSeparator className="relative mx-0 overflow-hidden before:absolute before:inset-0 before:origin-left before:scale-x-0 before:rounded-sm before:bg-success before:transition-transform before:duration-300 before:ease-out-cubic before:content-[''] group-data-[state=completed]/step:before:scale-x-100 motion-reduce:before:transition-none" />
                    ) : null}
                  </StepperItem>
                ),
              )}
            </StepperNav>
          </Stepper>
        </div>

        {/* A measured height, not `layout`. `layout` replays the change as a
            transform on the element itself, so the real box resizes at once
            and the Card and the dialog around it jump — measured 263px to
            681px in a single frame. Animating the measured height is what
            `StepBody` in persona-wizard already does here, and it is the only
            version the ancestors can follow.

            It is also what lets min-h-72 go: that was holding the footer still
            by reserving the tallest step's height on every step, which is why
            a two-field step sat in a half-empty card.

            The clip is on only while the height moves — kept permanently it
            cuts the focus ring off a field at the container's edge. */}
        <CardContent>
          <motion.div
            animate={{ height }}
            className={morphing ? "overflow-hidden" : undefined}
            initial={false}
            onAnimationComplete={() => setMorphing(false)}
            onAnimationStart={() => setMorphing(true)}
            transition={reduce ? { duration: 0 } : RESIZE}
          >
            <div ref={innerRef}>
              <AnimatePresence custom={direction} initial={false} mode="wait">
                <motion.div
                  animate="enter"
                  custom={direction}
                  exit="exit"
                  initial="hidden"
                  key={currentStep}
                  transition={reduce ? { duration: 0 } : undefined}
                  variants={variants}
                >
                  {children}
                </motion.div>
              </AnimatePresence>
            </div>
          </motion.div>
        </CardContent>

        {/* Below the body and above the footer, and deliberately outside the
            AnimatePresence: it describes the submit, not the step, so it must
            not slide away when the reader moves. Card pads its own children,
            so this matches CardContent rather than inventing a value. */}
        {notice ? <div className="px-(--card-spacing)">{notice}</div> : null}

        <CardFooter className="flex items-center justify-between gap-4 border-t">
          <div>{footerContent}</div>
          <div className="flex gap-2">
            {currentStep > 1 ? (
              <Button
                disabled={nextDisabled}
                onClick={onBack}
                variant="outline"
              >
                {backButtonText}
              </Button>
            ) : null}
            <Button disabled={nextDisabled} onClick={onNext}>
              {nextButtonText}
            </Button>
          </div>
        </CardFooter>
      </Card>
    )
  },
)

